Gherkin:
Feature: Enable Image Tagging in MCP Settings

  Scenario: User enables Image Tagging in Asset Intelligence
    Given the user is on the MCP settings page under Asset Intelligence
    When the user enables the "Enable Image Tagging" setting
    Then the platform should use Azure for image tagging
    And the "Azure Image Processing Limit (Images) (per billing cycle)" setting should be visible
    And the "Azure Video Processing Limit (minutes) (per billing cycle)" setting should be updated

Python:
from behave import given, when, then

@given('the user is on the MCP settings page under Asset Intelligence')
def step_given_user_on_mcp_settings_page(context):
    context.browser.get('https://example.com/mcp-settings/asset-intelligence')

@when('the user enables the "Enable Image Tagging" setting')
def step_when_user_enables_image_tagging(context):
    enable_image_tagging_checkbox = context.browser.find_element_by_id('enable-image-tagging')
    if not enable_image_tagging_checkbox.is_selected():
        enable_image_tagging_checkbox.click()

@then('the platform should use Azure for image tagging')
def step_then_platform_uses_azure(context):
    assert context.platform.image_tagging_service == 'Azure'

@then('the "Azure Image Processing Limit (Images) (per billing cycle)" setting should be visible')
def step_then_azure_image_processing_limit_visible(context):
    azure_image_limit = context.browser.find_element_by_id('azure-image-processing-limit')
    assert azure_image_limit.is_displayed()

@then('the "Azure Video Processing Limit (minutes) (per billing cycle)" setting should be updated')
def step_then_azure_video_processing_limit_updated(context):
    azure_video_limit = context.browser.find_element_by_id('azure-video-processing-limit')
    assert 'minutes' in azure_video_limit.text

