@given('the form builder is configured with "Allow User to Add More Records" enabled')
def step_given_form_builder_configured(context):
    context.form_builder_configured = True

@given('there are less than 30 child records in the configuration')
def step_given_less_than_30_child_records(context):
    context.child_records_count = 29

@when('the user attempts to add a new child record')
def step_when_user_attempts_to_add(context):
    if context.form_builder_configured and context.child_records_count < 30:
        context.add_record_attempt = True
    else:
        context.add_record_attempt = False

@then('the new child record is successfully added')
def step_then_record_successfully_added(context):
    assert context.add_record_attempt is True

