Gherkin:
Feature: Deselect items to not apply bulk changes

  Scenario: Deselecting items prevents bulk changes from being applied
    Given a list of resources with some selected and some de-selected
    And new data is entered in bulk Main Details, Tags, Filters, Custom Upload Fields, and Workflows
    When the user selects 'Apply to Selected'
    Then only the selected resources should have the updates applied
    And the de-selected resources should remain unchanged

Python:
from behave import given, when, then

@given('a list of resources with some selected and some de-selected')
def step_given_list_of_resources(context):
    context.resources = {'selected': ['resource1', 'resource2'], 'deselected': ['resource3', 'resource4']}

@given('new data is entered in bulk Main Details, Tags, Filters, Custom Upload Fields, and Workflows')
def step_given_new_data_entered(context):
    context.new_data = {'Main Details': 'new details', 'Tags': 'new tags', 'Filters': 'new filters', 'Custom Upload Fields': 'new fields', 'Workflows': 'new workflows'}

@when("the user selects 'Apply to Selected'")
def step_when_apply_to_selected(context):
    context.applied_resources = context.resources['selected']

@then('only the selected resources should have the updates applied')
def step_then_selected_resources_updated(context):
    assert context.applied_resources == ['resource1', 'resource2']

@then('the de-selected resources should remain unchanged')
def step_then_deselected_resources_unchanged(context):
    assert context.resources['deselected'] == ['resource3', 'resource4']

