Gherkin:
Feature: Update collaborators in a workflow request

  Scenario: Successfully update collaborators using PATCH call
    Given a workflow request with existing collaborators
    When I send a PATCH request to update the collaborators
    Then the collaborators should be updated successfully

Python:
from behave import given, when, then

@given('a workflow request with existing collaborators')
def step_given_workflow_request_with_collaborators(context):
    context.workflow_request = {'collaborators': ['user1', 'user2']}

@when('I send a PATCH request to update the collaborators')
def step_when_send_patch_request(context):
    context.updated_collaborators = ['user3', 'user4']
    context.response = patch_workflow_request(context.workflow_request, context.updated_collaborators)

@then('the collaborators should be updated successfully')
def step_then_collaborators_updated(context):
    assert context.response['collaborators'] == context.updated_collaborators

def patch_workflow_request(workflow_request, new_collaborators):
    workflow_request['collaborators'] = new_collaborators
    return workflow_request

