Gherkin:
Feature: Undo and Redo Resizing and Repositioning

  Scenario: User undoes and redoes resizing of an image
    Given the user has resized an image by dragging the dots
    When the user clicks on the Undo button
    Then the image returns to its original size
    When the user clicks on the Redo button
    Then the image returns to the resized state

Python:
from behave import given, when, then

@given('the user has resized an image by dragging the dots')
def step_given_user_resized_image(context):
    # Simulate user resizing the image
    context.image_resized = True

@when('the user clicks on the Undo button')
def step_when_user_clicks_undo(context):
    # Simulate clicking the Undo button
    if context.image_resized:
        context.image_resized = False

@then('the image returns to its original size')
def step_then_image_original_size(context):
    assert not context.image_resized

@when('the user clicks on the Redo button')
def step_when_user_clicks_redo(context):
    # Simulate clicking the Redo button
    if not context.image_resized:
        context.image_resized = True

@then('the image returns to the resized state')
def step_then_image_resized_state(context):
    assert context.image_resized

