Gherkin:
Feature: Bulk Review with Hide Decline Handling

  Scenario: Bulk Review with mixed Hide Decline settings
    Given a list of requests with mixed Hide Decline settings
    When the user selects Decline and applies in bulk
    Then Decline is applied only to items without Hide Decline
    And items with Hide Decline remain pending
    And Decline is hidden if all remaining items have Hide Decline

Python:
from behave import given, when, then

@given('a list of requests with mixed Hide Decline settings')
def step_given_mixed_hide_decline_settings(context):
    context.requests = [
        {'id': 1, 'hide_decline': False},
        {'id': 2, 'hide_decline': True},
        {'id': 3, 'hide_decline': False}
    ]

@when('the user selects Decline and applies in bulk')
def step_when_user_applies_decline_in_bulk(context):
    context.declined_requests = [
        request for request in context.requests if not request['hide_decline']
    ]

@then('Decline is applied only to items without Hide Decline')
def step_then_decline_applied_to_non_hidden(context):
    assert all(not request['hide_decline'] for request in context.declined_requests)

@then('items with Hide Decline remain pending')
def step_then_items_with_hide_decline_pending(context):
    pending_requests = [
        request for request in context.requests if request['hide_decline']
    ]
    assert len(pending_requests) == 1

@then('Decline is hidden if all remaining items have Hide Decline')
def step_then_decline_hidden_if_all_remaining_have_hide_decline(context):
    remaining_requests = [
        request for request in context.requests if request not in context.declined_requests
    ]
    if all(request['hide_decline'] for request in remaining_requests):
        context.decline_hidden = True
    assert context.decline_hidden

