Gherkin:
Feature: Delete Widget with underlying Block

  Scenario: User deletes a Widget and its underlying Block
    Given a Widget with an underlying Block exists
    When the User deletes the Widget
    Then the Widget and the underlying Block are deleted
    And the User can undo the deletion
    And the User can redo the deletion
    And the system triggers an unsaved change notification

Python:
from behave import given, when, then

@given('a Widget with an underlying Block exists')
def step_given_widget_with_block_exists(context):
    context.widget = create_widget_with_block()

@when('the User deletes the Widget')
def step_when_user_deletes_widget(context):
    context.widget.delete()

@then('the Widget and the underlying Block are deleted')
def step_then_widget_and_block_deleted(context):
    assert not context.widget.exists()
    assert not context.widget.block.exists()

@then('the User can undo the deletion')
def step_then_user_can_undo_deletion(context):
    context.widget.undo_delete()
    assert context.widget.exists()
    assert context.widget.block.exists()

@then('the User can redo the deletion')
def step_then_user_can_redo_deletion(context):
    context.widget.redo_delete()
    assert not context.widget.exists()
    assert not context.widget.block.exists()

@then('the system triggers an unsaved change notification')
def step_then_unsaved_change_notification(context):
    assert context.system.unsaved_change_triggered()

