Gherkin:
Feature: Undo and Redo actions for Widget and Block

  Scenario: User can undo and redo adding, removing, and moving Widgets with Blocks
    Given a page with no Widgets and Blocks
    When the user adds a Widget with a Block to the page
    And the user removes the Widget with the Block from the page
    And the user moves the Widget with the Block on the page
    Then the user can undo the last action
    And the user can redo the last undone action

Python:
from behave import given, when, then

@given('a page with no Widgets and Blocks')
def step_given_page_with_no_widgets_and_blocks(context):
    context.page = Page()
    assert context.page.is_empty()

@when('the user adds a Widget with a Block to the page')
def step_when_user_adds_widget_with_block(context):
    context.page.add_widget_with_block()
    assert context.page.has_widget_with_block()

@when('the user removes the Widget with the Block from the page')
def step_when_user_removes_widget_with_block(context):
    context.page.remove_widget_with_block()
    assert not context.page.has_widget_with_block()

@when('the user moves the Widget with the Block on the page')
def step_when_user_moves_widget_with_block(context):
    context.page.move_widget_with_block()
    assert context.page.widget_with_block_moved()

@then('the user can undo the last action')
def step_then_user_can_undo_last_action(context):
    context.page.undo_last_action()
    assert context.page.last_action_undone()

@then('the user can redo the last undone action')
def step_then_user_can_redo_last_undone_action(context):
    context.page.redo_last_undone_action()
    assert context.page.last_action_redone()

