Gherkin:
Feature: Bulk Review Selection

  Scenario: Select items for Bulk Review based on Workflow Template
    Given an Approval List with multiple requests using the same Workflow Template
    When the user selects one request from the Approval List
    Then all requests using the same Workflow Template are selected for Bulk Review

Python:
from behave import given, when, then

@given('an Approval List with multiple requests using the same Workflow Template')
def step_given_approval_list_with_template(context):
    context.approval_list = [
        {'id': 1, 'template': 'TemplateA'},
        {'id': 2, 'template': 'TemplateA'},
        {'id': 3, 'template': 'TemplateB'}
    ]
    context.selected_template = 'TemplateA'

@when('the user selects one request from the Approval List')
def step_when_user_selects_request(context):
    context.selected_request = context.approval_list[0]

@then('all requests using the same Workflow Template are selected for Bulk Review')
def step_then_requests_selected_for_bulk_review(context):
    selected_requests = [
        request for request in context.approval_list
        if request['template'] == context.selected_template
    ]
    assert len(selected_requests) == 2

