Feature: Detect and modify response for non-matching params in BulkReview

  Scenario: Modify response when requests have non-matching params
    Given a BulkReview component with multiple requests
    When the requests have non-matching params
    Then the response section is modified accordingly

Python:
from behave import given, when, then

@given('a BulkReview component with multiple requests')
def step_given_bulk_review_component(context):
    context.requests = [
        {'param1': 'value1', 'param2': 'value2'},
        {'param1': 'value1', 'param2': 'different_value'}
    ]

@when('the requests have non-matching params')
def step_when_requests_have_non_matching_params(context):
    context.non_matching = any(
        req['param2'] != context.requests[0]['param2'] for req in context.requests
    )

@then('the response section is modified accordingly')
def step_then_response_is_modified(context):
    assert context.non_matching is True
    context.response_modified = True

