Gherkin:
Feature: Stats report for database tool

  Scenario: Run stats report and display files from multi upload field
    Given a database tool with a multi upload field containing multiple files
    When the user runs the stats report
    Then each file from the multi upload field is represented on its own row

Python:
from behave import given, when, then

@given('a database tool with a multi upload field containing multiple files')
def step_given_database_tool_with_multi_upload(context):
    context.files = ['file1.txt', 'file2.txt', 'file3.txt']

@when('the user runs the stats report')
def step_when_user_runs_stats_report(context):
    context.report = generate_stats_report(context.files)

@then('each file from the multi upload field is represented on its own row')
def step_then_files_represented_on_own_row(context):
    assert len(context.report) == len(context.files)
    for file in context.files:
        assert file in context.report

